SOLVERS = [
 dict(id='art14', title='Is the law valid under Article 14?', use='A law or order treats one group differently from another.', steps=[
  ('Identify the classification and the object', 'State who is included, who is left out, and what the law is trying to achieve. Name the object from the statute, its preamble or its context.', ['dalmia', 'kathi']),
  ('Intelligible differentia', 'Is there a real, understandable difference between those included and those left out — not an arbitrary or fanciful one?', ['dalmia', 'anwar', 'balsara']),
  ('Rational nexus', 'Does that difference have a rational relation to the object of the law? Test it against the object you identified.', ['dalmia', 'nakara', 'motorgeneral']),
  ('Special situations', 'Single-entity laws (Chiranjit Lal); unguided discretion (Anwar Ali v. Kathi Raning, Moopil Nair); wide latitude for tax and economic laws (R.K. Garg, East India Tobacco); classification that loses its nexus over time (Motor General Traders); step-by-step, under-inclusive laws (Ambica Mills).', ['chiranjit', 'moopil', 'rkgarg', 'motorgeneral', 'ambica']),
  ('Non-arbitrariness', 'Even if the classification passes, is the State action arbitrary? Arbitrariness is the antithesis of equality.', ['royappa', 'maneka', 'ajayhasia', 'shayara']),
  ('Conclude', 'Valid or invalid, and why — name the limb that decides it. If invalid, say whether the bad part can be severed.', ['rmdc']),
 ]),
 dict(id='art19', title='Is the restriction on an Article 19 freedom valid?', use='A law or order limits speech, assembly, association, movement, residence or occupation.', steps=[
  ('Is the claimant a citizen?', 'Art 19 protects citizens only. Companies cannot claim it, but shareholders can; foreigners cannot.', ['hansmuller', 'rccooper', 'bennett']),
  ('Which freedom, and is it directly affected?', 'Name the sub-clause. Ask whether the direct and inevitable effect of the measure falls on that freedom.', ['bennett', 'sakal', 'express1958']),
  ('Is there a "law"?', 'A restriction must be imposed by law; executive instructions alone are not enough.', ['bijoe', 'kharak']),
  ('A permitted ground in the matching clause', 'Speech: Art 19(2)\'s eight grounds; assembly 19(3); association 19(4); movement and residence 19(5); occupation 19(6). The grounds are exhaustive.', ['romesh', 'kaushal']),
  ('Is it reasonable?', 'Substance and procedure; nature of the right, the evil, proportion (V.G. Row); proximate, not remote, nexus (Lohia 1960, Rangarajan); only incitement, not discussion or advocacy (Shreya Singhal); not excessive (Chintaman Rao); proportionality (Anuradha Bhasin).', ['vgrow', 'lohia1960', 'rangarajan', 'shreya', 'chintaman', 'anuradha']),
  ('Conclude', 'State the result clause by clause; distinguish law and order from public order where relevant (Lohia 1965).', ['lohia1965']),
 ]),
 dict(id='art21', title='Has Article 21 been violated?', use='Someone is deprived of life or personal liberty, or a claim is made under the expanded Art 21.', steps=[
  ('Who is the claimant?', 'Art 21 protects every person — citizens and non-citizens.', ['hansmuller']),
  ('Is life or personal liberty engaged?', '"Life" is more than animal existence; it includes dignity, livelihood, privacy, speedy trial, education up to 14 and more.', ['kharak', 'francis', 'olga', 'hussainara', 'puttaswamy']),
  ('Is the deprivation by procedure established by law?', 'There must be a valid law; the procedure must be fair, just and reasonable, not arbitrary.', ['maneka', 'satwant']),
  ('Golden triangle', 'Test the same law against Art 14 and the relevant Art 19 freedoms — the rights are not watertight compartments.', ['maneka', 'rccooper']),
  ('Substantive fairness', 'A law can fail even with procedure if it is substantively unjust — for example, a mandatory death sentence.', ['mithu', 'bachan']),
  ('Emergency and remedies', 'Arts 20 and 21 cannot be suspended (Art 359 after the 44th Amendment). Compensation is available for custodial violations.', ['admjabalpur', 'dkbasu']),
 ]),
 dict(id='art13', title='Is the law void under Article 13?', use='A statute conflicts with a Fundamental Right and you must say what happens to it.', steps=[
  ('Pre- or post-Constitution?', 'Laws in force before 26 January 1950 fall under Art 13(1); later laws under Art 13(2).', ['keshavan']),
  ('Pre-Constitution law: eclipse', 'Void only to the extent of inconsistency and only from 26 January 1950; dormant, not dead — it revives if the Fundamental Right is later amended.', ['bhikaji', 'keshavan']),
  ('Post-Constitution law: still-born', 'Void from inception and not revived by a later amendment — but where the right is for citizens only, the law still operates against non-citizens.', ['deepchand', 'saghir', 'ambica']),
  ('Severability', 'Strike only what is void if the rest is a complete, workable code and the legislature would have enacted it alone.', ['rmdc', 'gopalan', 'balsara', 'romesh']),
  ('Waiver', 'Fundamental rights cannot be waived.', ['basheshar', 'olga']),
  ('Is it "law" at all?', 'Uncodified personal law (Narasu Appa Mali) and constitutional amendments (Art 13(4)) are outside Art 13.', ['narasu', 'shankari', 'kesavananda']),
 ]),
 dict(id='amend', title='Is the constitutional amendment valid?', use='An amendment is challenged.', steps=[
  ('Procedure under Art 368(2)', 'Special majority in each House; ratification by half the States for the provisos (federal provisions, Art 368 itself).', []),
  ('Art 13 does not apply', 'After the 24th Amendment (Arts 13(4), 368(3)) an amendment is not "law" under Art 13 — Golak Nath no longer applies.', ['golaknath', 'kesavananda']),
  ('Basic structure', 'Does the amendment damage or destroy an essential feature — supremacy of the Constitution, judicial review, limited amending power, the FR–DPSP balance, rule of law?', ['kesavananda', 'minerva']),
  ('Ninth Schedule laws', 'Laws added after 24 April 1973 can be tested against Part III and the basic structure.', ['waman', 'coelho']),
  ('Conclude', 'Valid, or struck down to the extent it violates the basic structure.', []),
 ]),
 dict(id='resv', title='Is the reservation valid (Arts 15(4), 16(4))?', use='A reservation or special provision for a backward class is challenged.', steps=[
  ('Is the group a backward class?', 'Social and educational backwardness; caste can be an indicator but not the sole test for 15(4) (Balaji); for 16(4) a caste can be a class (Indra Sawhney).', ['mrbalaji', 'indra']),
  ('Creamy layer', 'The advanced members must be excluded for OBCs; it also applies to SC/ST in promotions (Jarnail Singh).', ['indra', 'jarnail']),
  ('50% ceiling', 'Reservation should ordinarily not exceed 50%; carry-forward cannot breach it (Devadasan); EWS reservation sits outside it (Janhit Abhiyan).', ['indra', 'devadasan', 'janhit']),
  ('Promotions', 'Arts 16(4A) and (4B); the State must justify inadequacy of representation and keep efficiency in view (Art 335).', ['nagaraj', 'jarnail']),
  ('Is it equality or an exception?', 'Arts 15(4) and 16(4) are facets of equality, not exceptions to it.', ['nmthomas', 'indra']),
  ('Conversion', 'Backwardness tied to the Hindu social order does not automatically carry over after conversion.', ['sameer']),
 ]),
]

